   184→/**
   185→ * 执行一次真实问数：阶段一生成 SQL → 安全执行 → 阶段二生成解读，全程推导留痕（onTrace）。
   186→ * @param input 问数入参（问题/历史/Schema/数据源/权限/回调等，字段含义见 LiveQueryInput）
   187→ * @returns 四分支结果：成功（ok=true）/ 失败（ok=false，附错误诊断）/ 歧义澄清（ok='clarify'）/ 拒答（ok='refuse'）；
   188→ *          澄清与拒答仅在首轮首个候选上接受，重试与计划模式下按 SQL 契约直接执行
   189→ */
   190→export async function runLiveQuery(input: LiveQueryInput): Promise<LiveQueryOutcome> {
   191→  const { query, history, schema, guidance, dataSourceId, dsType, sensitiveRemoved } = input;
   192→  const trace = (step: TraceStep) => {
   193→    try {
   194→      input.onTrace?.(step);
   195→    } catch {
   196→      // 留痕失败不阻断主链路
   197→    }
   198→  };
   199→  const t0 = Date.now();
   200→  input.onStage?.('understanding');
   201→  // M2 计划模式：已批准计划先留痕，阶段一按其步骤引导生成（并跳过歧义澄清）
   202→  if (input.approvedPlan) {
   203→    trace({
   204→      stepType: 'plan',
   205→      title: '按已批准计划执行',
   206→      inputSummary: input.approvedPlan.understanding,
   207→      outputSummary: `${input.approvedPlan.steps.length} 个步骤：${input.approvedPlan.steps.map((s) => s.title).join(' → ')}`,
   208→      durationMs: Date.now() - t0,
   209→    });
   210→  }
   211→  // Schema Linking（借鉴 Chat2DB AI 数据集）：大 schema 时只把相关表注入 prompt（P2-9 关键词粗排 + embedding 精排）；
   212→  // 安全白名单（executeSafeSql）仍用全量 schema，召回遗漏不会误杀合法 SQL
   213→  const promptSchemaBase = await selectRelevantTablesAsync(schema, query);
   214→  trace({
   215→    stepType: 'linking',
   216→    title: 'Schema 圈表：选定相关表',
   217→    inputSummary: query,
   218→    outputSummary: `命中 ${promptSchemaBase.length}/${Array.isArray(schema) ? schema.length : 0} 张表：${promptSchemaBase.map((t) => String(t?.name || '')).join(', ')}`,
   219→    durationMs: Date.now() - t0,
   220→  });
   221→  // 上下文构建并行化：few-shot / 知识库 RAG / 外部知识库 / 语义指标 / 点踩反例 / 个人对话沉淀 / 铁律规则七者互不依赖，并发执行（各自失败不阻断）
   222→  const [fewShotPairs, knowledgeRaw, externalKb, metricHits, negativePairs, convPairs, ironRules] = await Promise.all([
   223→    // P0 Few-shot（DAIL-SQL 双维度）：用圈定表名引导样例贴近当前可查表
   224→    loadFewShotExamples(
   225→      dataSourceId,
   226→      query,
   227→      promptSchemaBase.map((t) => String(t?.name || ''))
   228→    ).catch(() => [] as FewShotExample[]),
   229→    // P1-A 知识库 RAG：检索业务知识片段注入 prompt，按 token 预算截断
   230→    retrieveKnowledgeSnippets(dataSourceId, query).catch(() => ''),
   231→    // 外部知识库接入：管理员配置的企业级外部 RAG 检索，与本地知识一并作为自主学习来源（单源失败降级空）
   232→    searchExternalKnowledge(dataSourceId, query).catch(() => null),
   233→    // P1-1 语义指标层：问题命中指标名/同义词时模板化注入权威口径
   234→    loadActiveMetrics(dataSourceId)
   235→      .then((ms) => matchMetrics(query, ms))
   236→      .catch(() => []),
   237→    // 自主学习·反例：同数据源点踩问答对作为反面教材注入阶段一 prompt
   238→    loadNegativeExamples(dataSourceId, query).catch(() => [] as NegativeExample[]),
   239→    // 自主学习·个人沉淀：本人同数据源历史成功问答对作为个人 few-shot
   240→    loadConversationFewShot(
   241→      input.userId,
   242→      dataSourceId,
   243→      query,
   244→      promptSchemaBase.map((t) => String(t?.name || ''))
   245→    ).catch(() => []),
   246→    // 铁律规则库（v0.9.35）：该数据源全部 ACTIVE 铁律恒注入（最高优先级强制约束，不按问题匹配）
   247→    loadActiveIronRules(dataSourceId).catch(() => []),
   248→  ]);
   249→  // Vanna 借鉴：few-shot 以 user/assistant 消息对注入对话历史（比平铺文本更贴合 LLM 多轮格式）；
   250→  // 团队样例库在前，个人对话沉淀在后，均为「先问题后 SQL」格式
   251→  const fewShotHistory: ChatMessage[] = [
   252→    ...fewShotPairs.map((ex) => ({ question: ex.question, sql: ex.sql })),
   253→    ...convPairs,
   254→  ].flatMap((ex) => [
   255→    { role: 'user' as const, content: ex.question },
   256→    { role: 'assistant' as const, content: ex.sql },
   257→  ]);
   258→  const knowledge = budgetText(knowledgeRaw, KNOWLEDGE_TOKEN_BUDGET);
   259→  // 外部知识库片段独立预算控制，追加在本地知识之后（互不挤占注入槽位）
   260→  const externalSnippet = externalKb?.snippet || '';
   261→  trace({
   262→    stepType: 'knowledge',
   263→    title: '知识库检索与 Few-shot 样例',
   264→    inputSummary: query,
   265→    outputSummary: `知识片段 ${knowledge ? knowledge.length : 0} 字${externalSnippet ? `；外部知识库 ${externalSnippet.length} 字（成功 ${externalKb?.okSources ?? 0} 源${externalKb?.failSources ? `，失败 ${externalKb.failSources} 源` : ''}）` : ''}；few-shot 样例 ${fewShotPairs.length} 组（个人沉淀 ${convPairs.length} 组）；点踩反例 ${negativePairs.length} 组`,
   266→    durationMs: Date.now() - t0,
   267→  });
   268→  const metricPrompt = buildMetricPrompt(metricHits);
   269→  if (metricHits.length > 0) {
   270→    trace({
   271→      stepType: 'metrics',
   272→      title: '语义指标层命中',
   273→      inputSummary: query,
   274→      outputSummary: `命中 ${metricHits.length} 个指标定义：${metricHits.map((m) => m.name).join('、')}`,
   275→      durationMs: Date.now() - t0,
   276→    });
   277→  }
   278→  // 铁律规则全量恒注入（v0.9.35）：ACTIVE 即最高优先级强制约束，注入留痕便于推导审计
   279→  const ironRulesPrompt = buildIronRulesPrompt(ironRules);
   280→  if (ironRules.length > 0) {
   281→    trace({
   282→      stepType: 'metrics',
   283→      title: '铁律规则注入',
   284→      inputSummary: query,
   285→      outputSummary: `注入 ${ironRules.length} 条铁律：${ironRules.map((r) => r.title).join('、')}`,
   286→      durationMs: Date.now() - t0,
   287→    });
   288→  }
   289→  // P1-5 列级 Schema Linking：宽表（>50 列）圈表后再做列级相关性排序，仅注入 top-N 相关列
   290→  // + 指标层引用列/主键（强制保留），降低宽表 prompt token 占用；安全白名单仍用全量 schema
   291→  const columnPrune = await pruneWideTableColumnsAsync(promptSchemaBase, query, metricColumnsByTable(metricHits));
   292→  const promptSchema = columnPrune.tables;
   293→  if (columnPrune.pruned.length > 0) {
   294→    trace({
   295→      stepType: 'linking',
   296→      title: '列级裁剪：宽表 top-N 列注入',
   297→      inputSummary: query,
   298→      outputSummary: columnPrune.pruned.map((p) => `${p.table} ${p.before}→${p.after} 列`).join('；'),
   299→      durationMs: Date.now() - t0,
   300→    });
   301→  }
   302→  // M3 中间表清洗链：复杂度评估自动触发（multi-step）或「深度分析」开关强制；
   303→  // 清洗结果落库应用库中间表，阶段一可引用（仅引用 ait_* 时改在应用库执行）
   304→  let chainTables: IntermediateTableInfo[] = [];
   305→  const assessAt = Date.now();
   306→  // 深度分析开关强制时需 LLM 产出清洗计划（force）；否则启发式预门控无信号直接判 simple
   307→  const assessment = await assessComplexity(query, promptSchema, { force: Boolean(input.deepAnalysis) });
   308→  trace({
   309→    stepType: 'plan',
   310→    title: '复杂度评估',
   311→    inputSummary: query,
   312→    outputSummary: assessment.complexity === 'multi-step' ? `多步复杂分析，清洗计划 ${assessment.steps.length} 步` : '简单问题，直接生成 SQL',
   313→    durationMs: Date.now() - assessAt,
   314→  });
   315→  if (input.deepAnalysis || assessment.complexity === 'multi-step') {
   316→    const chain = await runAnalysisChain({
   317→      question: query,
   318→      dataSourceId,
   319→      schema,
   320→      sensitiveRemoved,
   321→      assessment,
   322→      userId: input.userId,
   323→      traceId: input.traceId,
   324→      onTrace: input.onTrace,
   325→    }).catch(() => null);
   326→    if (chain) chainTables = chain.tables;
   327→  }
   328→  const stage1System = buildStage1System(promptSchema, guidance, knowledge + externalSnippet, fewShotPairs.length + convPairs.length, dsType, Boolean(input.allowIntrospection), input.approvedPlan, chainTables, metricPrompt, negativePairs, input.dataSourceName, ironRulesPrompt);
   329→  // 多轮历史按 token 预算截断（保留最近轮次），与 few-shot 消息对拼接后注入阶段一
   330→  const budgetedHistory = budgetHistory(history);
   331→  // 专家角色路由：库化配置按 sortOrder 升序关键词匹配（仅 ADMIN 维护，v0.9.40），库异常时回退内置常量
   332→  const persona = await resolveExpertPersonaAsync(query);
   333→
   334→  let retries = 0;
   335→  let plan: Stage1Plan | null = null;
   336→  let exec: Awaited<ReturnType<typeof executeSafeSql>> | null = null;
   337→  let lastError = '';
   338→  // EXPLAIN 防线拦截标记：LLM 最多获得一次"收窄条件"自纠错机会，二次拦截即终止（防自纠错空转）
   339→  let guardBlocked = false;
   340→  // 数据自省仅首次尝试允许一轮（防止递归内省拖慢响应）
   341→  let introspected = false;
   342→
   343→  // P1-7 自纠错：按问题结构复杂度分档生成多候选（Self-Consistency 多数表决择优）。
   344→  // 复杂信号：schema linking 圈定 ≥2 张表（多表 JOIN 场景）或复杂度评估判定需清洗链（multi-step/嵌套）。
   345→  // 注意：assessment.complexity 的语义是「是否需要中间清洗链」，不等于 SQL 结构复杂度，不能单独作分档依据。
   346→  // P0 性能优化：小模型路由表数阈值环境变量化（LLM_SQL_ROUTE_MAX_TABLES，默认 1 = 仅单表走快速模型，v0.5.0 原行为）。
   347→  // 设为 2 时双表非 multi-step 查询也走快速模型（提速 3~5 倍）；
   348→  // 注意实测风险：快速模型在多表 JOIN 时易漏 COUNT(DISTINCT) 造成重复计数，放宽后需关注准确率回归（可设回 1 一键回退）。
   349→  const sqlRouteMaxTables = (() => {
   350→    const raw = Number(process.env.LLM_SQL_ROUTE_MAX_TABLES);
   351→    return Number.isFinite(raw) && raw >= 1 ? Math.floor(raw) : 1;
   352→  })();
   353→  const isComplexQuery = assessment.complexity === 'multi-step' || promptSchema.length > sqlRouteMaxTables;
   354→  const candidateCount = selfCorrectCandidates(isComplexQuery);
   355→  // 阶段一模型分档：简单单表问题走配置的快速模型路由（flash），复杂/多表问题强制主模型。
   356→  // 实测快速模型在多表 JOIN 时易漏 COUNT(DISTINCT) 造成重复计数，且同源多候选多数表决无法纠正系统性偏差，
   357→  // 故复杂问题以口径正确性优先（P1-7 多候选择优仍保留）；未配置 LLM_SQL_* 时 sqlStageRoute() 返回 undefined 全程主模型。
   358→  const stage1Route = isComplexQuery ? undefined : sqlStageRoute();
   359→
   360→  // v0.4.15 C2: 模板匹配前置——优先尝试用 LLM 做"模板选择 + 参数填充"，命中则直接用模板引擎确定性拼装 SQL
   361→  // 背景：本地开源模型自由生成复杂 SQL（窗口函数/同比环比）可靠性弱于云端旗舰，确定性模板零偏差兜底
   362→  let templateSql: string | null = null;
   363→  let matchedTemplateId: string | null = null;
   364→  if (!input.approvedPlan && AVAILABLE_TEMPLATES.length > 0) {
   365→    try {
   366→      // 轻量 LLM 调用：输出 {templateId,params}；未命中时返回 null
   367→      const templateMatchPrompt = `你是一个模板选择引擎。根据用户问题和 Schema，判断是否命中以下分析模板之一。若命中则输出 JSON{"templateId":"<id>","params":{<paramSchema>}}; 否则输出 null。
   368→
   369→可用模板:
   370→${AVAILABLE_TEMPLATES.map((t, i) => `${i + 1}. [${t.id}] ${t.label}: ${t.description}`).join('\n')}
   371→
   372→Schema: ${serializeSchemaForPrompt(schema)}
   373→
   374→用户问题：${query}
   375→
   376→仅输出纯 JSON 或 null，不要任何 markdown 标记。`;
   377→      const matchRaw = await callLLMJson(templateMatchPrompt, query, [], { route: stage1Route }).catch(() => null);
   378→      const matchResult = matchRaw ? (safeParseJson(matchRaw) as { templateId?: string; params?: Record<string, unknown> } | null) : null;
   379→      if (matchResult?.templateId && matchResult.params) {
   380→        // templateId 来自 LLM 输出的动态字符串，此处单次受控断言收窄类型；非法值由 validateTemplateParams 白名单校验拒绝
