    63→  deepAnalysis: boolean;
    64→  /** M2 计划模式已批准 planId（缺失 → ''） */
    65→  planId: string;
    66→}
    67→
    68→/** 增量 SSE 事件发射器：由路由实现（重放缓冲 + HTTP 流写入），服务侧只声明发射语义 */
    69→export interface QueryEventSink {
    70→  /** 发射一个 SSE 事件（非流式模式或连接已结束时为 no-op） */
    71→  send(event: string, data: unknown): void;
    72→  /** 是否已写出首个 SSE 事件（异常兜底分支据此选择 SSE error 事件或 JSON 500） */
    73→  started(): boolean;
