    79→export type QueryOutcome =
    80→  /** 直接 JSON 响应（全部早退 4xx 与 SSE 未开始时的异常兜底 5xx） */
    81→  | { kind: 'json'; status: number; body: unknown }
    82→  /** 200 结果体：streamAware=true 且流式模式下由路由发 SSE(event)+end，否则 JSON */
    83→  | { kind: 'result'; event: string; body: unknown; streamAware: boolean }
