    90→ */
    91→export async function runNaturalLanguageQuery(
    92→  params: NaturalLanguageParams,
    93→  sink: QueryEventSink
    94→): Promise<QueryOutcome> {
    95→  const startedAt = Date.now();
    96→  const { user, traceId, dataSourceId } = params;
    97→  const streamMode = params.stream;
    98→  const auditBase = {
    99→    userId: user.id,
   100→    username: user.username,
   101→    endpoint: 'query' as const,
   102→    dataSourceId,
   103→  };
   104→
   105→  // L2 权限层：Service 侧复核（与路由 requireRole 构成 Controller+Service 双层校验）
   106→  if (user.role !== 'ADMIN' && user.role !== 'ANALYST') {
   107→    writeAudit({ ...auditBase, status: 'DENIED_AUTH', detail: `角色 ${user.role} 无问数权限`, durationMs: Date.now() - startedAt });
   108→    return { kind: 'json', status: 403, body: { code: ERROR_CODES.FORBIDDEN, error: '当前角色没有智能问数权限' } };
   109→  }
   110→
   111→  // P2-11 数据源访问控制：非 ADMIN 需命中部门/个人授权清单
   112→  if (auditBase.dataSourceId && !(await checkDataSourceAccess(user, auditBase.dataSourceId))) {
   113→    writeAudit({ ...auditBase, status: 'DENIED_AUTH', detail: '无数据源访问权限（ACL）', durationMs: Date.now() - startedAt });
   114→    return { kind: 'json', status: 403, body: { code: ERROR_CODES.DS_ACCESS_DENIED, error: '没有该数据源的访问权限，可向管理员申请开通' } };
   115→  }
